/* === 运营平台扩展（Figma 运营平台 Page） === */
.drawer-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.35);
  z-index: 1200; display: flex; justify-content: flex-end;
}
.drawer-overlay.hidden { display: none !important; }
.drawer-panel {
  width: 640px; max-width: 100vw; height: 100%;
  background: var(--bg-white); box-shadow: var(--shadow-lg);
  display: flex; flex-direction: column;
}
.drawer-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 20px; border-bottom: 1px solid var(--border);
}
.drawer-head h3 { font-size: 16px; font-weight: 600; margin: 0; }
.drawer-tabs {
  display: flex; gap: 4px; padding: 12px 20px 0; border-bottom: 1px solid var(--border);
}
.drawer-tabs button {
  border: none; background: transparent; padding: 8px 14px;
  font-size: 13px; color: var(--text-muted); cursor: pointer;
  border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.drawer-tabs button.active {
  color: var(--primary); font-weight: 600; border-bottom-color: var(--primary);
}
.drawer-body { flex: 1; overflow-y: auto; padding: 12px 20px 20px; }
.drawer-item {
  padding: 12px 14px; border: 1px solid var(--border); border-radius: var(--radius-md);
  margin-bottom: 10px; cursor: pointer; transition: border-color 0.15s;
}
.drawer-item:hover { border-color: var(--primary); background: #fafcff; }
.drawer-item.unread { border-left: 3px solid var(--primary); }
.drawer-item .di-title { font-size: 14px; font-weight: 500; margin-bottom: 4px; }
.drawer-item .di-meta { font-size: 12px; color: var(--text-muted); }

.ops-tabs {
  display: flex; gap: 4px; margin-bottom: 16px;
  border-bottom: 1px solid var(--border); padding-bottom: 0;
}
.ops-tabs button {
  border: none; background: transparent; padding: 10px 16px;
  font-size: 14px; color: var(--text-muted); cursor: pointer;
  border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.ops-tabs button.active {
  color: var(--primary); font-weight: 600; border-bottom-color: var(--primary);
}
.ops-tab-panel { display: none; }
.ops-tab-panel.active { display: block; }

.context-menu {
  position: fixed; z-index: 1300; min-width: 112px;
  background: var(--bg-white); border: 1px solid var(--border);
  border-radius: var(--radius-md); box-shadow: var(--shadow-md);
  padding: 4px 0; display: none;
}
.context-menu.open { display: block; }
.context-menu button {
  display: block; width: 100%; text-align: left;
  border: none; background: transparent; padding: 8px 14px;
  font-size: 13px; color: var(--text); cursor: pointer;
}
.context-menu button:hover { background: var(--bg-hover); color: var(--primary); }

.ops-task-layout {
  display: grid; grid-template-columns: 1fr 320px; gap: 16px;
}
.ops-task-main .card { margin-bottom: 16px; }
.ops-task-side .card { margin-bottom: 12px; }
.ops-kv-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 24px;
}
.ops-kv-grid .ops-kv { border: none; padding: 0; flex-direction: column; align-items: flex-start; gap: 4px; }
.ops-kv-grid .ops-kv .k { font-size: 12px; }

.ops-inline-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ops-role-badge {
  display: inline-block; padding: 2px 8px; border-radius: 4px;
  font-size: 11px; background: var(--primary-light); color: var(--primary);
}

.modal-overlay { z-index: 1100; }
.modal-overlay.hidden { display: none !important; }
.modal-box.modal-sm { width: 480px; }
.modal-box.modal-md { width: 560px; }
.modal-box.modal-lg { width: 944px; max-width: calc(100vw - 32px); }

.ops-flow-chart {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 16px; background: var(--bg-page); border-radius: var(--radius-md);
}
.ops-flow-node {
  padding: 8px 14px; border: 1px solid var(--border); border-radius: var(--radius-md);
  background: var(--bg-white); font-size: 13px;
}
.ops-flow-arrow { color: var(--text-muted); font-size: 18px; }

.org-tree { padding: 8px 0; }
.org-tree ul { list-style: none; padding-left: 20px; margin: 4px 0; }
.org-tree > ul { padding-left: 0; }
.org-tree li {
  padding: 6px 10px; border-left: 2px solid var(--border);
  margin: 4px 0; font-size: 13px;
}
.org-tree li strong { color: var(--text); }

.topbar-bell { position: relative; }
.topbar-bell .badge-dot {
  position: absolute; top: 4px; right: 4px; width: 8px; height: 8px;
  background: var(--danger); border-radius: 50%; border: 2px solid #fff;
}

