/**
 * 运营平台共享壳：角色、modal、侧栏占位链接、消息中心挂载
 */
(function (global) {
  function params() {
    return new URLSearchParams((global.location && global.location.search) || '');
  }

  function getRole() {
    var r = params().get('role');
    if (r === 'expert' || r === 'team' || r === 'ops') return r;
    var path = (global.location && global.location.pathname) || '';
    if (path.indexOf('12-expert') >= 0) return 'expert';
    if (path.indexOf('11-user-feedback') >= 0) return 'ops';
    return 'ops';
  }

  function href(page, extra) {
    var q = new URLSearchParams();
    Object.keys(extra || {}).forEach(function (k) {
      if (extra[k] != null && extra[k] !== '') q.set(k, extra[k]);
    });
    if (!q.has('role')) q.set('role', getRole());
    var qs = q.toString();
    return page + (qs ? '?' + qs : '');
  }

  function openModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.remove('hidden');
  }

  function closeModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add('hidden');
  }

  function bindModalClose(root) {
    (root || document).querySelectorAll('[data-close-modal]').forEach(function (btn) {
      if (btn.dataset.modalCloseWired) return;
      btn.dataset.modalCloseWired = '1';
      btn.addEventListener('click', function () {
        closeModal(btn.getAttribute('data-close-modal'));
      });
    });
    (root || document).querySelectorAll('.modal-overlay').forEach(function (overlay) {
      if (overlay.dataset.overlayWired) return;
      overlay.dataset.overlayWired = '1';
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) overlay.classList.add('hidden');
      });
    });
  }

  function bindTabs(containerSel) {
    var root = document.querySelector(containerSel);
    if (!root) return;
    root.querySelectorAll('[data-ops-tab]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var tab = btn.getAttribute('data-ops-tab');
        root.querySelectorAll('[data-ops-tab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        document.querySelectorAll('[data-ops-panel]').forEach(function (p) {
          p.classList.toggle('active', p.getAttribute('data-ops-panel') === tab);
        });
      });
    });
  }

  function wireOpsSidebarLinks() {
    document.querySelectorAll('.sidebar a[href="11-user-feedback.html"], .sidebar a[href="12-expert-workbench.html"], .sidebar a[href="13-permission-mgmt.html"]').forEach(function (a) {
      if (a.dataset.opsSidebarWired) return;
      a.dataset.opsSidebarWired = '1';
      var base = a.getAttribute('href').split('?')[0];
      a.href = href(base);
    });
  }

  function initShell(opts) {
    opts = opts || {};
    if (global.Proto && Proto.initTopbar) Proto.initTopbar('ops');
    wireOpsSidebarLinks();
    bindModalClose(document);
    if (opts.tabs) bindTabs(opts.tabs);
    if (global.OpsMessageCenter && OpsMessageCenter.mount) {
      OpsMessageCenter.mount(getRole());
    }
  }

  global.OpsShell = {
    params: params,
    getRole: getRole,
    href: href,
    openModal: openModal,
    closeModal: closeModal,
    bindModalClose: bindModalClose,
    bindTabs: bindTabs,
    initShell: initShell
  };
})(window);

/**
 * 消息中心 drawer（topbar 铃铛）
 */
(function (global) {
  var KEY = 'proto_ops_messages';

  var DEFAULT_MESSAGES = [
    { id: 'msg_001', type: 'todo', role: 'ops', title: '待审核专家任务', body: '采购流程优化任务待运营审核', at: '2026-06-04 09:20', read: false },
    { id: 'msg_002', type: 'todo', role: 'expert', title: '新任务已分派', body: '用户反馈 #FB-1024 已分配给您', at: '2026-06-04 08:45', read: false },
    { id: 'msg_003', type: 'announce', role: 'ops', title: '平台维护通知', body: '6 月 5 日 02:00–04:00 例行维护', at: '2026-06-03 18:00', read: true },
    { id: 'msg_004', type: 'todo', role: 'team', title: '团队待处理反馈', body: '模型团队有 2 条反馈待处理', at: '2026-06-04 10:05', read: false }
  ];

  function load() {
    try {
      var raw = sessionStorage.getItem(KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    try {
      sessionStorage.setItem(KEY, JSON.stringify(DEFAULT_MESSAGES));
    } catch (e2) {}
    return DEFAULT_MESSAGES.slice();
  }

  function save(list) {
    try {
      sessionStorage.setItem(KEY, JSON.stringify(list));
    } catch (e) {}
  }

  function unreadCount(role) {
    return load().filter(function (m) {
      return !m.read && (m.role === role || m.role === 'all');
    }).length;
  }

  function ensureDrawerDom() {
    if (document.getElementById('opsMessageDrawer')) return;
    var html =
      '<div class="drawer-overlay hidden" id="opsMessageDrawer">' +
      '  <div class="drawer-panel">' +
      '    <div class="drawer-head">' +
      '      <h3>消息中心</h3>' +
      '      <button type="button" class="icon-btn" data-close-drawer="opsMessageDrawer">✕</button>' +
      '    </div>' +
      '    <div class="drawer-tabs" id="opsMessageTabs">' +
      '      <button type="button" class="active" data-msg-tab="todo">待办</button>' +
      '      <button type="button" data-msg-tab="announce">公告</button>' +
      '    </div>' +
      '    <div class="drawer-body" id="opsMessageBody"></div>' +
      '  </div>' +
      '</div>';
    document.body.insertAdjacentHTML('beforeend', html);
    document.getElementById('opsMessageDrawer').addEventListener('click', function (e) {
      if (e.target.id === 'opsMessageDrawer') closeDrawer();
    });
    document.querySelector('[data-close-drawer="opsMessageDrawer"]').addEventListener('click', closeDrawer);
    document.querySelectorAll('#opsMessageTabs [data-msg-tab]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        document.querySelectorAll('#opsMessageTabs [data-msg-tab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        renderList(btn.getAttribute('data-msg-tab'));
      });
    });
  }

  function openDrawer() {
    ensureDrawerDom();
    document.getElementById('opsMessageDrawer').classList.remove('hidden');
    renderList('todo');
  }

  function closeDrawer() {
    var el = document.getElementById('opsMessageDrawer');
    if (el) el.classList.add('hidden');
  }

  function renderList(tab) {
    var body = document.getElementById('opsMessageBody');
    if (!body) return;
    var role = global.OpsShell ? OpsShell.getRole() : 'ops';
    var items = load().filter(function (m) {
      return m.type === tab && (m.role === role || m.role === 'all' || (role === 'ops' && m.role === 'team'));
    });
    if (!items.length) {
      body.innerHTML = '<div class="empty-state" style="border:none;padding:32px 0;">暂无' + (tab === 'todo' ? '待办' : '公告') + '</div>';
      return;
    }
    body.innerHTML = items.map(function (m) {
      return '<div class="drawer-item' + (m.read ? '' : ' unread') + '" data-msg-id="' + m.id + '">' +
        '<div class="di-title">' + m.title + '</div>' +
        '<div class="di-meta">' + m.body + ' · ' + m.at + '</div></div>';
    }).join('');
    body.querySelectorAll('[data-msg-id]').forEach(function (row) {
      row.addEventListener('click', function () {
        var id = row.getAttribute('data-msg-id');
        var list = load();
        var item = list.find(function (x) { return x.id === id; });
        if (item) {
          item.read = true;
          save(list);
          row.classList.remove('unread');
          updateBadge();
          if (global.Proto && Proto.toast) Proto.toast('已读：' + item.title);
        }
      });
    });
  }

  function updateBadge() {
    var role = global.OpsShell ? OpsShell.getRole() : 'ops';
    var n = unreadCount(role);
    document.querySelectorAll('.topbar-bell').forEach(function (bell) {
      var dot = bell.querySelector('.badge-dot');
      if (n > 0) {
        if (!dot) {
          dot = document.createElement('span');
          dot.className = 'badge-dot';
          bell.appendChild(dot);
        }
      } else if (dot) {
        dot.remove();
      }
    });
  }

  function wireBellButtons() {
    document.querySelectorAll('.topbar-bell button, button[data-ops-bell]').forEach(function (btn) {
      if (btn.dataset.bellWired) return;
      btn.dataset.bellWired = '1';
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        openDrawer();
      });
    });
  }

  function mount(role) {
    ensureDrawerDom();
    wireBellButtons();
    updateBadge();
  }

  global.OpsMessageCenter = {
    load: load,
    save: save,
    mount: mount,
    openDrawer: openDrawer,
    closeDrawer: closeDrawer,
    unreadCount: unreadCount
  };
})(window);

/**
 * 任务分派共享弹窗：指定团队/专家、修改截止时间、多人处理
 */
(function (global) {
  function ensureModals() {
    if (document.getElementById('dispatchTeamModal')) return;
    var html =
      '<div class="modal-overlay hidden" id="dispatchTeamModal">' +
      '  <div class="modal-box modal-lg">' +
      '    <div class="modal-header"><h2>指定团队处理</h2><button type="button" class="close" data-close-modal="dispatchTeamModal">✕</button></div>' +
      '    <div class="modal-body">' +
      '      <p style="font-size:13px;color:var(--text-muted);margin-bottom:12px;">当前反馈问题已自动归因，请选择处理团队</p>' +
      '      <div class="form-row"><span class="form-label">处理状态</span><div class="form-control"><span class="tag tag-warn">待处理</span></div></div>' +
      '      <div class="form-row"><span class="form-label required">指定团队</span><div class="form-control">' +
      '        <select class="select" id="dispatchTeamSelect"><option>模型团队</option><option>应用团队</option><option>平台团队</option></select>' +
      '      </div></div>' +
      '    </div>' +
      '    <div class="modal-footer">' +
      '      <button type="button" class="btn" data-close-modal="dispatchTeamModal">取消</button>' +
      '      <button type="button" class="btn btn-primary" id="confirmDispatchTeam">确认分派</button>' +
      '    </div></div></div>' +

      '<div class="modal-overlay hidden" id="dispatchExpertModal">' +
      '  <div class="modal-box modal-lg">' +
      '    <div class="modal-header"><h2>指定专家处理</h2><button type="button" class="close" data-close-modal="dispatchExpertModal">✕</button></div>' +
      '    <div class="modal-body">' +
      '      <div class="form-row"><span class="form-label">指定团队</span><div class="form-control"><span class="tag tag-info">模型团队</span></div></div>' +
      '      <div class="form-row"><span class="form-label required">选择专家</span><div class="form-control">' +
      '        <select class="select" id="dispatchExpertSelect"><option>李专家</option><option>王专家</option><option>赵专家</option></select>' +
      '      </div></div>' +
      '    </div>' +
      '    <div class="modal-footer">' +
      '      <button type="button" class="btn" data-close-modal="dispatchExpertModal">取消</button>' +
      '      <button type="button" class="btn btn-primary" id="confirmDispatchExpert">确认分派</button>' +
      '    </div></div></div>' +

