    var pool = loadTasks().filter(function (t) { return t.pool === 'public'; });
    document.getElementById('expertMyTasksBody').innerHTML = renderTaskRows(mine, 'mine') || '<tr><td colspan="5" class="empty-state" style="border:none;">暂无进行中的任务</td></tr>';
    document.getElementById('expertPoolBody').innerHTML = renderTaskRows(pool, 'pool') || '<tr><td colspan="5" class="empty-state" style="border:none;">任务池为空</td></tr>';
    document.querySelectorAll('[data-claim-task]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var id = btn.getAttribute('data-claim-task');
        var list = loadTasks().map(function (t) {
          if (t.id !== id) return t;
          return Object.assign({}, t, { status: 'in_progress', expert: '当前专家', pool: 'assigned' });
        });
        saveTasks(list);
        Proto.toast('已领取任务');
        initWorkbenchPage();
      });
