/**
 * 通用右键/更多操作菜单（Figma context menu 帧）
 */
(function (global) {
  var menuEl = null;
  var hideHandler = null;

  function ensureMenu() {
    if (menuEl) return menuEl;
    menuEl = document.createElement('div');
    menuEl.className = 'context-menu';
    menuEl.id = 'opsContextMenu';
    menuEl.setAttribute('role', 'menu');
    document.body.appendChild(menuEl);
    return menuEl;
  }

  function hide() {
    if (menuEl) menuEl.classList.remove('open');
    if (hideHandler) {
      document.removeEventListener('click', hideHandler);
      document.removeEventListener('contextmenu', hideHandler);
      hideHandler = null;
    }
  }

  function show(x, y, items) {
    var menu = ensureMenu();
    menu.innerHTML = items.map(function (item) {
      if (item.divider) return '<hr class="context-divider">';
      var cls = item.danger ? ' danger' : '';
      return '<button type="button" class="context-item' + cls + '" data-action="' + (item.action || '') + '">' + item.label + '</button>';
    }).join('');
    menu.style.left = Math.min(x, window.innerWidth - 160) + 'px';
    menu.style.top = Math.min(y, window.innerHeight - items.length * 36 - 8) + 'px';
    menu.classList.add('open');
    menu.querySelectorAll('.context-item').forEach(function (btn, idx) {
      var item = items.filter(function (i) { return !i.divider; })[idx];
      if (!item) return;
      btn.addEventListener('click', function (e) {
        e.stopPropagation();
        hide();
        if (typeof item.onClick === 'function') item.onClick();
      });
    });
    hideHandler = function () { hide(); };
    setTimeout(function () {
      document.addEventListener('click', hideHandler);
      document.addEventListener('contextmenu', hideHandler);
    }, 0);
  }

  function wireRowActions(row, itemsBuilder) {
    if (row.dataset.ctxWired) return;
    row.dataset.ctxWired = '1';
    row.addEventListener('contextmenu', function (e) {
      e.preventDefault();
      var items = itemsBuilder(row);
      if (items && items.length) show(e.clientX, e.clientY, items);
    });
    var more = row.querySelector('[data-row-menu]');
    if (more) {
      more.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var rect = more.getBoundingClientRect();
        var items = itemsBuilder(row);
        if (items && items.length) show(rect.left, rect.bottom + 4, items);
      });
    }
  }

  global.OpsContextMenu = {
    show: show,
    hide: hide,
    wireRowActions: wireRowActions
  };
})(window);

/**
 * 运营平台共享壳：角色、modal、统一侧栏/顶栏、breadcrumb
 */
(function (global) {
  var SIDEBAR_LINKS = {
    data: [
      { href: '11-user-feedback.html', icon: '💬', label: '用户反馈', module: 'feedback' },
      { href: '12-expert-workbench.html', icon: '👥', label: '专家工作台', module: 'expert' }
    ],
    manage: [
      { href: 'index.html', icon: '📦', label: '智能体运营', module: 'ops' },
      { href: '08-audit-queue.html', icon: '✅', label: '审核工作台', module: 'audit' },
      { href: '13-permission-mgmt.html', icon: '🛡️', label: '权限与开发者管理', module: 'permission' }
    ]
  };

  var ROLE_LABELS = { ops: '运营视角', expert: '专家视角', team: '团队视角' };

  function params() {
    return new URLSearchParams((global.location && global.location.search) || '');
  }

  function currentPage() {
    var path = (global.location && global.location.pathname) || '';
    var base = path.split('/').pop() || 'index.html';
    return base.split('?')[0];
  }

  function getRole() {
    var r = params().get('role');
    if (r === 'expert' || r === 'team' || r === 'ops') return r;
    var page = currentPage();
    if (page.indexOf('12-expert') >= 0) return 'expert';
    if (page.indexOf('11-user-feedback') >= 0) return 'ops';
    if (page.indexOf('13-permission') >= 0 || page.indexOf('13-org') >= 0) return 'ops';
    return 'ops';
  }

  function href(page, extra) {
    var q = new URLSearchParams();
    Object.keys(extra || {}).forEach(function (k) {
      if (extra[k] != null && extra[k] !== '') q.set(k, extra[k]);
    });
    if (!q.has('role')) q.set('role', getRole());
    var qs = q.toString();
    return page + (qs ? '?' + qs : '');
  }

  function openModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.remove('hidden');
  }

  function closeModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add('hidden');
  }

  function bindModalClose(root) {
    (root || document).querySelectorAll('[data-close-modal]').forEach(function (btn) {
      if (btn.dataset.modalCloseWired) return;
      btn.dataset.modalCloseWired = '1';
      btn.addEventListener('click', function () {
        closeModal(btn.getAttribute('data-close-modal'));
      });
    });
    (root || document).querySelectorAll('.modal-overlay').forEach(function (overlay) {
      if (overlay.dataset.overlayWired) return;
      overlay.dataset.overlayWired = '1';
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) overlay.classList.add('hidden');
      });
    });
  }

  function bindTabs(containerSel) {
    var root = typeof containerSel === 'string' ? document.querySelector(containerSel) : containerSel;
    if (!root) return;
    root.querySelectorAll('[data-ops-tab]').forEach(function (btn) {
      if (btn.dataset.tabWired) return;
      btn.dataset.tabWired = '1';
      btn.addEventListener('click', function () {
        var tab = btn.getAttribute('data-ops-tab');
        root.querySelectorAll('[data-ops-tab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        document.querySelectorAll('[data-ops-panel]').forEach(function (p) {
          p.classList.toggle('active', p.getAttribute('data-ops-panel') === tab);
        });
      });
    });
  }

  function bindSubTabs(containerSel) {
    var root = typeof containerSel === 'string' ? document.querySelector(containerSel) : containerSel;
    if (!root) return;
    root.querySelectorAll('[data-ops-subtab]').forEach(function (btn) {
      if (btn.dataset.subtabWired) return;
      btn.dataset.subtabWired = '1';
      btn.addEventListener('click', function () {
        var tab = btn.getAttribute('data-ops-subtab');
        root.querySelectorAll('[data-ops-subtab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        var panelRoot = root.closest('[data-ops-panel]') || document;
        panelRoot.querySelectorAll('[data-ops-subpanel]').forEach(function (p) {
          p.classList.toggle('active', p.getAttribute('data-ops-subpanel') === tab);
        });
      });
    });
  }

  function renderSidebar(activeModule, activePage) {
    activePage = activePage || currentPage();
    function linkHtml(link) {
      var isActive = link.href === activePage || link.module === activeModule;
      return '<a href="' + href(link.href) + '" class="' + (isActive ? 'active' : '') + '"><span class="icon">' + link.icon + '</span> ' + link.label + '</a>';
    }
    return '<div class="sidebar-section">' +
      '<div class="sidebar-title">数据</div>' +
      SIDEBAR_LINKS.data.map(linkHtml).join('') +
      '</div><div class="sidebar-section">' +
      '<div class="sidebar-title">管理</div>' +
      SIDEBAR_LINKS.manage.map(linkHtml).join('') +
      '</div>';
  }

  function renderTopbar(subtitle, showRoleBadge) {
    var role = getRole();
    var roleBadge = showRoleBadge && role !== 'ops'
      ? '<span class="ops-role-badge">' + (ROLE_LABELS[role] || role) + '</span>'
      : '';
    return '<div class="topbar-inner" style="max-width:var(--frame);margin:0 auto;display:flex;align-items:center;width:100%;">' +
      '<div class="topbar-brand">' +
      '<div class="topbar-logo">A</div>' +
      '<div class="topbar-brand-text"><strong>敖钦 AI</strong><span>' + (subtitle || '运营平台') + '</span></div>' +
      '</div>' +
      '<div class="topbar-modules">' +
      '<a href="06-dev-platform.html" data-nav-dev>智能体开发</a>' +
      '<a href="' + href('index.html') + '" class="active" data-nav-ops>运营平台</a>' +
      '</div>' +
      '<div class="topbar-right">' + roleBadge +
      '<span class="topbar-bell"><button class="icon-btn" type="button" data-ops-bell title="消息中心">🔔</button></span>' +
      '<div class="avatar"></div></div></div>';
  }

  function renderLayout(opts) {
    opts = opts || {};
    var body = document.body;
    var module = opts.module || body.getAttribute('data-ops-module') || 'ops';
    var page = opts.activePage || body.getAttribute('data-ops-page') || currentPage();
    var subtitle = opts.subtitle || body.getAttribute('data-ops-subtitle') || '运营平台';
    var showRole = opts.showRoleBadge !== false;

    var topbar = document.querySelector('.topbar');
    if (topbar) topbar.innerHTML = renderTopbar(subtitle, showRole);

    var sidebar = document.querySelector('.sidebar');
    if (sidebar) sidebar.innerHTML = renderSidebar(module, page);

    wireBreadcrumbs();
    wireOpsSidebarLinks();
  }

  function wireBreadcrumbs() {
    document.querySelectorAll('.breadcrumb a[href]').forEach(function (a) {
      if (a.dataset.bcWired) return;
      var raw = a.getAttribute('href');
      if (!raw || raw === '#' || raw.indexOf('http') === 0) return;
      a.dataset.bcWired = '1';
      var base = raw.split('?')[0];
      a.href = href(base);
    });
    document.querySelectorAll('a[data-ops-href]').forEach(function (a) {
      if (a.dataset.opsHrefWired) return;
      a.dataset.opsHrefWired = '1';
      var page = a.getAttribute('data-ops-href');
      var extra = {};
      try {
        var extraRaw = a.getAttribute('data-ops-params');
        if (extraRaw) Object.assign(extra, JSON.parse(extraRaw));
      } catch (e) {}
      a.href = href(page, extra);
    });
  }

  function wireOpsSidebarLinks() {
    document.querySelectorAll('.sidebar a[href]').forEach(function (a) {
      if (a.dataset.opsSidebarWired) return;
      a.dataset.opsSidebarWired = '1';
      var base = a.getAttribute('href').split('?')[0];
      if (base && base !== '#') a.href = href(base);
    });
  }

  function initShell(opts) {
    opts = opts || {};
    if (document.body.getAttribute('data-ops-module') || opts.module) {
      renderLayout(opts);
    } else {
      wireOpsSidebarLinks();
      wireBreadcrumbs();
    }
    if (global.Proto && Proto.initTopbar) Proto.initTopbar('ops');
    bindModalClose(document);
    if (opts.tabs) bindTabs(opts.tabs);
    if (opts.subtabs) bindSubTabs(opts.subtabs);
    if (global.OpsMessageCenter && OpsMessageCenter.mount) {
      OpsMessageCenter.mount(getRole());
    }
  }

  global.OpsShell = {
    params: params,
    currentPage: currentPage,
    getRole: getRole,
    href: href,
    openModal: openModal,
    closeModal: closeModal,
    bindModalClose: bindModalClose,
    bindTabs: bindTabs,
    bindSubTabs: bindSubTabs,
    renderLayout: renderLayout,
    renderSidebar: renderSidebar,
    renderTopbar: renderTopbar,
    wireBreadcrumbs: wireBreadcrumbs,
    initShell: initShell
  };
})(window);

/**
 * 用户反馈模块
 */
(function (global) {
  var KEY = 'proto_ops_feedback';

  var DEFAULT = [
    { id: 'fb_001', title: '模型回答与文档不一致', user: '张三', team: '模型团队', status: 'pending', priority: 'high', source: '客服助手', createdAt: '2026-06-04 09:12', desc: '用户咨询产品规格时，回答与知识库文档存在偏差' },
    { id: 'fb_002', title: '响应延迟超过 30 秒', user: '李四', team: '平台团队', status: 'processing', priority: 'medium', source: '数据分析助手', createdAt: '2026-06-03 16:40', desc: '高峰时段响应明显变慢' },
    { id: 'fb_003', title: 'Skills 未按预期触发', user: '王五', team: '应用团队', status: 'resolved', priority: 'low', source: '采购申请助手', createdAt: '2026-06-02 11:05', desc: '绑定 Skill 后对话中未出现预期能力' },
    { id: 'fb_004', title: '多轮对话上下文丢失', user: '赵六', team: '模型团队', status: 'pending', priority: 'high', source: 'HR 助手', createdAt: '2026-06-04 08:20', desc: '第 3 轮开始无法引用前文信息' },
    { id: 'fb_005', title: '审核流程跳转失败', user: '钱七', team: '平台团队', status: 'processing', priority: 'medium', source: '采购申请助手', createdAt: '2026-06-03 14:15', desc: '点击提交后页面无响应' },
    { id: 'fb_006', title: '导出报表字段缺失', user: '孙八', team: '应用团队', status: 'pending', priority: 'low', source: '数据分析助手', createdAt: '2026-06-01 17:30', desc: 'CSV 导出缺少成本列' },
    { id: 'fb_007', title: '权限提示文案不准确', user: '周九', team: '平台团队', status: 'resolved', priority: 'low', source: '客服助手', createdAt: '2026-05-30 10:00', desc: '无权限时应提示联系管理员' },
    { id: 'fb_008', title: '夜间模式对比度不足', user: '吴十', team: '应用团队', status: 'pending', priority: 'medium', source: '智能编码伙伴', createdAt: '2026-06-04 11:45', desc: '深色主题下部分按钮难以辨认' }
  ];

  var filterState = { status: 'all', query: '' };

  function load() {
    try {
      var raw = sessionStorage.getItem(KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    try { sessionStorage.setItem(KEY, JSON.stringify(DEFAULT)); } catch (e2) {}
    return DEFAULT.slice();
  }

  function save(list) {
    try { sessionStorage.setItem(KEY, JSON.stringify(list)); } catch (e) {}
  }

  function byId(id) {
    return load().find(function (x) { return x.id === id; });
  }

  function statusTag(status) {
    var map = {
      pending: ['待处理', 'tag-warn'],
      processing: ['处理中', 'tag-info'],
      resolved: ['已解决', 'tag-ok']
    };
    return map[status] || map.pending;
  }

  function filteredList() {
    return load().filter(function (fb) {
      if (filterState.status !== 'all' && fb.status !== filterState.status) return false;
      if (filterState.query) {
        var q = filterState.query.toLowerCase();
        return (fb.title + fb.user + fb.team + fb.source).toLowerCase().indexOf(q) >= 0;
      }
      return true;
    });
  }

  function renderTable() {
    var tbody = document.getElementById('feedbackListBody');
    if (!tbody) return;
    var list = filteredList();
    if (!list.length) {
      tbody.innerHTML = '<tr><td colspan="7" class="empty-state" style="border:none;">暂无匹配的反馈</td></tr>';
      return;
    }
    tbody.innerHTML = list.map(function (fb) {
      var st = statusTag(fb.status);
      var detailUrl = OpsShell.href('11-user-feedback-detail.html', { id: fb.id });
      return '<tr data-fb-id="' + fb.id + '">' +
        '<td><strong>' + fb.title + '</strong><div style="font-size:12px;color:var(--text-muted);margin-top:2px;">' + fb.source + '</div></td>' +
        '<td>' + fb.user + '</td>' +
        '<td>' + fb.team + '</td>' +
        '<td><span class="tag ' + st[1] + '">' + st[0] + '</span></td>' +
        '<td style="color:var(--text-muted);">' + fb.createdAt + '</td>' +
        '<td class="ops-inline-actions">' +
        '<a href="' + detailUrl + '" class="btn btn-sm btn-primary">查看</a>' +
        '<button type="button" class="btn btn-sm btn-ghost" data-row-menu title="更多">⋯</button></td></tr>';
    }).join('');
    list.forEach(function (fb) {
      var row = tbody.querySelector('[data-fb-id="' + fb.id + '"]');
      if (!row || !global.OpsContextMenu) return;
      OpsContextMenu.wireRowActions(row, function () {
        var detailUrl = OpsShell.href('11-user-feedback-detail.html', { id: fb.id });
        return [
          { label: '查看详情', onClick: function () { window.location.href = detailUrl; } },
          { label: '分派团队', onClick: function () { window.location.href = detailUrl + '&action=dispatch'; } },
          { label: '标记已解决', onClick: function () {
            fb.status = 'resolved';
            save(load().map(function (x) { return x.id === fb.id ? fb : x; }));
            Proto.toast('已标记为已解决');
            renderTable();
          }}
        ];
      });
    });
  }

  function wireFilters() {
    var bar = document.querySelector('.filter-bar');
    if (!bar || bar.dataset.filterWired) return;
    bar.dataset.filterWired = '1';
    var statusMap = { '全部': 'all', '待处理': 'pending', '处理中': 'processing', '已解决': 'resolved' };
    bar.querySelectorAll('.filter-pills button').forEach(function (btn) {
      btn.addEventListener('click', function () {
        bar.querySelectorAll('.filter-pills button').forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        filterState.status = statusMap[btn.textContent.trim()] || 'all';
        renderTable();
      });
    });
    var search = bar.querySelector('.filter-search');
    if (search) {
      search.addEventListener('input', function () {
        filterState.query = search.value.trim();
        renderTable();
      });
    }
  }

  function processModalVariant(role, fb) {
    var modal = document.getElementById('feedbackProcessModal');
    if (!modal) return;
    var titleEl = modal.querySelector('.modal-header h2');
    var extraEl = document.getElementById('processExtraFields');
    var confirmBtn = document.getElementById('confirmProcessFeedback');
    var titles = {
      ops: fb.status === 'resolved' ? '（运营）归档反馈' : '（运营）处理反馈',
      team: fb.status === 'processing' ? '（团队负责人）更新进展' : '（团队负责人）处理反馈',
      personal: '（个人）处理反馈'
    };
    var effectiveRole = role === 'team' ? 'team' : (role === 'expert' ? 'personal' : 'ops');
    if (titleEl) titleEl.textContent = titles[effectiveRole] || '处理反馈';
    if (extraEl) {
      if (effectiveRole === 'ops' && fb.status !== 'resolved') {
        extraEl.innerHTML = '<div class="form-row"><span class="form-label">分派建议</span><div class="form-control"><select class="select" id="processTeamSuggest"><option>模型团队</option><option>平台团队</option><option>应用团队</option></select></div></div>';
      } else if (effectiveRole === 'team') {
        extraEl.innerHTML = '<div class="form-row"><span class="form-label">团队备注</span><div class="form-control"><input class="input" id="processTeamNote" placeholder="可选：团队内部备注"></div></div>';
      } else {
        extraEl.innerHTML = '';
      }
    }
    if (confirmBtn) {
      confirmBtn.textContent = fb.status === 'resolved' ? '确认归档' : '确认处理';
    }
  }

  function initListPage() {
    OpsShell.initShell({ module: 'feedback', subtitle: '用户反馈' });
    OpsDispatch.ensureModals();
    wireFilters();
    renderTable();
  }

  function initDetailPage() {
    OpsShell.initShell({ module: 'feedback', subtitle: '用户反馈' });
    OpsDispatch.ensureModals();
    var id = OpsShell.params().get('id') || 'fb_001';
    var fb = byId(id);
    if (!fb) {
      document.querySelector('.main').innerHTML = '<div class="card" style="padding:24px;text-align:center;">未找到反馈记录<a href="' + OpsShell.href('11-user-feedback.html') + '" class="btn btn-primary" style="margin-left:12px;">返回列表</a></div>';
      return;
    }
    var st = statusTag(fb.status);
    document.getElementById('fbTitle').textContent = fb.title;
    document.getElementById('fbUser').textContent = fb.user;
    document.getElementById('fbTeam').textContent = fb.team;
    document.getElementById('fbStatus').innerHTML = '<span class="tag ' + st[1] + '">' + st[0] + '</span>';
