      btn.dataset.bellWired = '1';
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        openDrawer();
      });
    });
  }

  function mount() {
    ensureDrawerDom();
    wireBellButtons();
    updateBadge();
  }

