}
.ops-subtabs button.active {
  border-color: var(--primary); color: var(--primary); background: var(--primary-light);
}
.btn-ghost { border: none; background: transparent; color: var(--text-muted); padding: 4px 8px; }
.btn-ghost:hover { color: var(--primary); background: var(--bg-hover); }
