  display: flex; align-items: center; gap: 12px;
}
.ops-kpi-label { font-size: 13px; font-weight: 600; min-width: 100px; }
.ops-peak-indicator {
  position: relative; flex: 1; max-width: 220px; height: 32px;
  background: var(--bg-page); border-radius: var(--radius-md);
  border: 1px solid var(--border); display: flex; align-items: center; padding: 0 8px;
}
.ops-peak-bar {
  height: 8px; background: linear-gradient(90deg, var(--primary), #22c55e);
  border-radius: 4px; max-width: calc(100% - 40px);
}
.ops-peak-value { margin-left: auto; font-size: 12px; font-weight: 600; }
