/**
 * 运营平台共享壳 — 对齐 Figma TopNav + 侧栏（与 index.html 一致）
 */
(function (global) {
  var SIDEBAR = [
    { section: '数据', links: [
      { href: '11-user-feedback.html', icon: '💬', label: '用户反馈', module: 'feedback' },
      { href: '12-expert-workbench.html', icon: '👥', label: '专家工作台', module: 'expert' }
    ]},
    { section: '分析', links: [
      { href: '#', icon: '📊', label: '业务看板', placeholder: true },
      { href: '#', icon: '🧠', label: '模型看板', placeholder: true },
      { href: '#', icon: '📈', label: '资源看板', placeholder: true },
      { href: '#', icon: '👤', label: '用户与智能体画像', placeholder: true }
    ]},
    { section: '管理', links: [
      { href: '#', icon: '⚙️', label: '模型运营', placeholder: true },
      { href: 'index.html', icon: '📦', label: '智能体运营', module: 'ops' },
      { href: '08-audit-queue.html', icon: '✅', label: '审核工作台', module: 'audit' },
      { href: '#', icon: '💰', label: '资源与成本管理', placeholder: true },
      { href: '13-permission-mgmt.html', icon: '🛡️', label: '权限与开发者管理', module: 'permission' }
    ]}
  ];

  var ROLE_LABELS = { ops: '运营视角', expert: '专家视角', team: '团队视角' };

  function params() {
    return new URLSearchParams((global.location && global.location.search) || '');
  }

  function currentPage() {
    var path = (global.location && global.location.pathname) || '';
    return (path.split('/').pop() || 'index.html').split('?')[0];
  }

  function getRole() {
    var r = params().get('role');
    if (r === 'expert' || r === 'team' || r === 'ops') return r;
    var page = currentPage();
    if (page.indexOf('12-expert') >= 0) return 'expert';
    return 'ops';
  }

  function href(page, extra) {
    var q = new URLSearchParams();
    Object.keys(extra || {}).forEach(function (k) {
      if (extra[k] != null && extra[k] !== '') q.set(k, extra[k]);
    });
    if (!q.has('role')) q.set('role', getRole());
    var qs = q.toString();
    return page + (qs ? '?' + qs : '');
  }

  function openModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.remove('hidden');
  }

  function closeModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add('hidden');
  }

  function bindModalClose(root) {
    (root || document).querySelectorAll('[data-close-modal]').forEach(function (btn) {
      if (btn.dataset.modalCloseWired) return;
      btn.dataset.modalCloseWired = '1';
      btn.addEventListener('click', function () {
        closeModal(btn.getAttribute('data-close-modal'));
      });
    });
    (root || document).querySelectorAll('.modal-overlay').forEach(function (overlay) {
      if (overlay.dataset.overlayWired) return;
      overlay.dataset.overlayWired = '1';
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) overlay.classList.add('hidden');
      });
    });
  }

  function bindTabs(containerSel) {
    var root = typeof containerSel === 'string' ? document.querySelector(containerSel) : containerSel;
    if (!root) return;
    root.querySelectorAll('[data-ops-tab]').forEach(function (btn) {
      if (btn.dataset.tabWired) return;
      btn.dataset.tabWired = '1';
      btn.addEventListener('click', function () {
        var tab = btn.getAttribute('data-ops-tab');
        root.querySelectorAll('[data-ops-tab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        document.querySelectorAll('[data-ops-panel]').forEach(function (p) {
          p.classList.toggle('active', p.getAttribute('data-ops-panel') === tab);
        });
      });
    });
  }

  function bindSubTabs(containerSel) {
    var root = typeof containerSel === 'string' ? document.querySelector(containerSel) : containerSel;
    if (!root) return;
    root.querySelectorAll('[data-ops-subtab]').forEach(function (btn) {
      if (btn.dataset.subtabWired) return;
      btn.dataset.subtabWired = '1';
      btn.addEventListener('click', function () {
        var tab = btn.getAttribute('data-ops-subtab');
        root.querySelectorAll('[data-ops-subtab]').forEach(function (b) {
          b.classList.toggle('active', b === btn);
        });
        var panelRoot = root.closest('[data-ops-panel]') || document;
        panelRoot.querySelectorAll('[data-ops-subpanel]').forEach(function (p) {
          p.classList.toggle('active', p.getAttribute('data-ops-subpanel') === tab);
        });
      });
    });
  }

  function renderSidebar(activeModule, activePage) {
    activePage = activePage || currentPage();
    return SIDEBAR.map(function (sec) {
      var links = sec.links.map(function (link) {
        var isActive = link.href === activePage || link.module === activeModule;
        var ph = link.placeholder ? ' data-ops-placeholder' : '';
        var h = link.placeholder ? '#' : href(link.href);
        return '<a href="' + h + '" class="' + (isActive ? 'active' : '') + '"' + ph + '><span class="icon">' + link.icon + '</span> ' + link.label + '</a>';
      }).join('');
      return '<div class="sidebar-section"><div class="sidebar-title">' + sec.section + '</div>' + links + '</div>';
    }).join('') +
      '<div class="sidebar-footer">' +
      '<a href="#" data-ops-placeholder>帮助文档</a>' +
      '<a href="' + href('11-user-feedback.html') + '">反馈建议</a>' +
      '</div>';
  }

  function renderTopbar(subtitle, showRoleBadge) {
    var role = getRole();
    var roleBadge = showRoleBadge && role !== 'ops'
      ? '<span class="ops-role-badge">' + (ROLE_LABELS[role] || role) + '</span>'
      : '';
    return '<div class="topbar-inner" style="max-width:var(--frame);margin:0 auto;display:flex;align-items:center;width:100%;">' +
      '<div class="topbar-brand">' +
      '<div class="topbar-logo">A</div>' +
      '<div class="topbar-brand-text"><strong>敖钦 AI</strong><span>企业级中台</span></div>' +
      '</div>' +
      '<div class="topbar-modules">' +
      '<span>智能编码伙伴</span>' +
      '<span>资源服务中心</span>' +
      '<span>模型服务</span>' +
      '<a href="06-dev-platform.html" data-nav-dev>智能体开发</a>' +
      '<span>智能编码</span>' +
      '<span>知识中心</span>' +
      '<a href="' + href('index.html') + '" class="active" data-nav-ops>运营平台</a>' +
      '</div>' +
      '<div class="topbar-right">' + roleBadge +
      '<input class="topbar-search" placeholder="搜索模型或任务..." aria-label="搜索">' +
      '<span class="topbar-bell"><button class="icon-btn" type="button" data-ops-bell title="消息中心">🔔</button></span>' +
      '<div class="avatar"></div></div></div>';
  }

  function renderLayout(opts) {
    opts = opts || {};
    var body = document.body;
    var module = opts.module || body.getAttribute('data-ops-module') || 'ops';
    var page = opts.activePage || body.getAttribute('data-ops-page') || currentPage();
    var topbar = document.querySelector('.topbar');
    if (topbar) topbar.innerHTML = renderTopbar(opts.subtitle, opts.showRoleBadge !== false);
    var sidebar = document.querySelector('.sidebar');
    if (sidebar) sidebar.innerHTML = renderSidebar(module, page);
    wireBreadcrumbs();
    wireOpsSidebarLinks();
    wirePlaceholders();
  }

  function wirePlaceholders() {
    document.querySelectorAll('[data-ops-placeholder]').forEach(function (a) {
      if (a.dataset.placeholderWired) return;
      a.dataset.placeholderWired = '1';
      a.addEventListener('click', function (e) {
        e.preventDefault();
        if (global.Proto && Proto.toast) Proto.toast('演示占位：该模块尚未开放');
      });
    });
  }

  function wireBreadcrumbs() {
    document.querySelectorAll('.breadcrumb a[href]').forEach(function (a) {
      if (a.dataset.bcWired) return;
      var raw = a.getAttribute('href');
      if (!raw || raw === '#' || raw.indexOf('http') === 0) return;
      a.dataset.bcWired = '1';
      a.href = href(raw.split('?')[0]);
    });
  }

  function wireOpsSidebarLinks() {
    document.querySelectorAll('.sidebar a[href]').forEach(function (a) {
      if (a.dataset.opsSidebarWired || a.hasAttribute('data-ops-placeholder')) return;
      a.dataset.opsSidebarWired = '1';
      var base = a.getAttribute('href').split('?')[0];
      if (base && base !== '#') a.href = href(base);
    });
  }

  function initShell(opts) {
    opts = opts || {};
    if (document.body.getAttribute('data-ops-module') || opts.module) {
      renderLayout(opts);
    } else {
      wireOpsSidebarLinks();
      wireBreadcrumbs();
      wirePlaceholders();
    }
    if (global.Proto && Proto.initTopbar) Proto.initTopbar('ops');
    bindModalClose(document);
    if (opts.tabs) bindTabs(opts.tabs);
    if (opts.subtabs) bindSubTabs(opts.subtabs);
    if (global.OpsMessageCenter && OpsMessageCenter.mount) OpsMessageCenter.mount(getRole());
  }

  global.OpsShell = {
    params: params,
    currentPage: currentPage,
    getRole: getRole,
    href: href,
    openModal: openModal,
    closeModal: closeModal,
    bindModalClose: bindModalClose,
    bindTabs: bindTabs,
    bindSubTabs: bindSubTabs,
    renderLayout: renderLayout,
    wireBreadcrumbs: wireBreadcrumbs,
    initShell: initShell
  };
})(window);

/**
 * 用户反馈模块 — 对齐 Figma 243:955 / 243:6859 文案与布局
 */
(function (global) {
  var KEY = 'proto_ops_feedback';

  var FIGMA_AGENTS = [
    '党建知识问答', '智能排期助手', '值班助手', '海域知识助手',
    '生产分析助手', '巡检助手', '生产安全顾问'
  ];

  var DEFAULT = [
    { id: 'fb_001', title: '回答与知识库条目不一致', user: '用户A', team: '模型团队', status: 'pending', type: '准确性', agent: '党建知识问答', createdAt: '2026-06-04', desc: '咨询党建流程时引用了过期政策版本' },
    { id: 'fb_002', title: '排期结果与日历冲突', user: '用户B', team: '应用团队', status: 'processing', type: '功能', agent: '智能排期助手', createdAt: '2026-06-03', desc: '自动排期未考虑节假日调休' },
    { id: 'fb_003', title: '值班提醒未推送', user: '用户C', team: '平台团队', status: 'pending', type: '稳定性', agent: '值班助手', createdAt: '2026-06-03', desc: '换班后 2 小时仍未收到提醒' },
    { id: 'fb_004', title: '海域法规引用错误', user: '用户D', team: '模型团队', status: 'resolved', type: '准确性', agent: '海域知识助手', createdAt: '2026-06-02', desc: '引用了已废止的海域管理条例' },
    { id: 'fb_005', title: '生产指标计算偏差', user: '用户E', team: '应用团队', status: 'processing', type: '数据', agent: '生产分析助手', createdAt: '2026-06-02', desc: 'OEE 计算与 MES 系统不一致' },
    { id: 'fb_006', title: '巡检路线遗漏点位', user: '用户F', team: '平台团队', status: 'pending', type: '功能', agent: '巡检助手', createdAt: '2026-06-01', desc: '新增设备未纳入默认巡检路线' },
    { id: 'fb_007', title: '安全规范问答不完整', user: '用户G', team: '模型团队', status: 'resolved', type: '准确性', agent: '生产安全顾问', createdAt: '2026-05-31', desc: '未提及 PPE 佩戴要求' },
    { id: 'fb_008', title: '多轮对话上下文丢失', user: '用户H', team: '模型团队', status: 'pending', type: '体验', agent: '党建知识问答', createdAt: '2026-05-30', desc: '第 3 轮无法引用前文' },
    { id: 'fb_009', title: '响应超时超过 30s', user: '用户I', team: '平台团队', status: 'processing', type: '性能', agent: '生产分析助手', createdAt: '2026-05-29', desc: '高峰时段频繁超时' },
    { id: 'fb_010', title: '导出报告字段缺失', user: '用户J', team: '应用团队', status: 'pending', type: '功能', agent: '智能排期助手', createdAt: '2026-05-28', desc: 'PDF 缺少负责人列' }
  ];

  var filterState = { query: '', scope: 'agent' };

  function load() {
    try {
      var raw = sessionStorage.getItem(KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    try { sessionStorage.setItem(KEY, JSON.stringify(DEFAULT)); } catch (e2) {}
    return DEFAULT.slice();
  }

  function save(list) {
    try { sessionStorage.setItem(KEY, JSON.stringify(list)); } catch (e) {}
  }

  function byId(id) {
    return load().find(function (x) { return x.id === id; });
  }

  function statusTag(status) {
    var map = {
      pending: ['待处理', 'tag-warn'],
      processing: ['处理中', 'tag-info'],
      resolved: ['已解决', 'tag-ok']
    };
    return map[status] || map.pending;
  }

  function filteredList() {
    return load().filter(function (fb) {
      if (filterState.query) {
        var q = filterState.query.toLowerCase();
        var hay = (fb.title + fb.agent + fb.type + fb.user).toLowerCase();
        if (hay.indexOf(q) < 0) return false;
      }
      return true;
    });
  }

  function renderTrendChart() {
    var el = document.getElementById('feedbackTrendChart');
    if (!el) return;
    var colors = ['#3b82f6', '#22c55e', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4', '#64748b'];
    var months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
    var legend = FIGMA_AGENTS.map(function (name, i) {
      return '<span class="ops-fb-legend-item"><i style="background:' + colors[i % colors.length] + '"></i>' + name + '</span>';
    }).join('');
    var bars = months.map(function (m, mi) {
      var segs = FIGMA_AGENTS.map(function (_, ai) {
        var h = 20 + ((mi + ai) * 7) % 55;
        return '<span class="ops-fb-bar-seg" style="height:' + h + '%;background:' + colors[ai % colors.length] + '"></span>';
      }).join('');
      return '<div class="ops-fb-bar-col"><div class="ops-fb-bar-stack">' + segs + '</div><span class="ops-fb-bar-label">' + m + '</span></div>';
    }).join('');
    el.innerHTML =
      '<div class="ops-fb-chart-legend">' + legend + '</div>' +
      '<div class="ops-fb-chart-bars">' + bars + '</div>';
  }

  function renderTable() {
    var tbody = document.getElementById('feedbackListBody');
    if (!tbody) return;
    var list = filteredList();
    if (!list.length) {
      tbody.innerHTML = '<tr><td colspan="6" class="empty-state" style="border:none;">暂无匹配的反馈</td></tr>';
      return;
    }
    tbody.innerHTML = list.map(function (fb) {
      var st = statusTag(fb.status);
      var detailUrl = OpsShell.href('11-user-feedback-detail.html', { id: fb.id });
      return '<tr data-fb-id="' + fb.id + '">' +
        '<td><strong>' + fb.title + '</strong></td>' +
        '<td>' + (fb.agent || '—') + '</td>' +
        '<td>' + (fb.type || '—') + '</td>' +
        '<td><span class="tag ' + st[1] + '">' + st[0] + '</span></td>' +
        '<td style="color:var(--text-muted);">' + fb.createdAt + '</td>' +
        '<td class="ops-inline-actions">' +
        '<a href="' + detailUrl + '" class="btn btn-sm btn-primary">查看</a>' +
        '<button type="button" class="btn btn-sm btn-ghost" data-row-menu title="更多">⋯</button></td></tr>';
    }).join('');
    list.forEach(function (fb) {
      var row = tbody.querySelector('[data-fb-id="' + fb.id + '"]');
      if (!row || !global.OpsContextMenu) return;
      OpsContextMenu.wireRowActions(row, function () {
        var detailUrl = OpsShell.href('11-user-feedback-detail.html', { id: fb.id });
        return [
          { label: '查看', onClick: function () { window.location.href = detailUrl; } },
          { label: '分派任务', onClick: function () { window.location.href = detailUrl + '&action=dispatch'; } },
          { label: '运营审核', onClick: function () { Proto.toast('已加入运营处理队列（演示）'); } }
        ];
      });
    });
  }

  function wireFilters() {
    var search = document.getElementById('feedbackSearchInput');
    if (search && !search.dataset.wired) {
      search.dataset.wired = '1';
      search.addEventListener('input', function () {
        filterState.query = search.value.trim();
        renderTable();
      });
    }
    var tabs = document.getElementById('feedbackScopeTabs');
    if (tabs && !tabs.dataset.wired) {
      tabs.dataset.wired = '1';
      tabs.querySelectorAll('[data-scope-tab]').forEach(function (btn) {
        btn.addEventListener('click', function () {
          tabs.querySelectorAll('[data-scope-tab]').forEach(function (b) { b.classList.remove('active'); });
          btn.classList.add('active');
          filterState.scope = btn.getAttribute('data-scope-tab');
          Proto.toast('已切换至「' + btn.textContent.trim() + '」视图（演示）');
        });
      });
    }
  }

  function processStatusRadios(role) {
    var opsOpts = ['已完成', '无需处理', '团队处理'];
    var teamOpts = ['已完成', '无需处理', '成员处理'];
    var personalOpts = ['已完成', '无需处理', '专家处理'];
    var labels = role === 'team' ? teamOpts : (role === 'expert' ? personalOpts : opsOpts);
    return '<div class="form-row"><span class="form-label">处理状态</span><div class="form-control">' +
      '<div class="ops-process-radios">' +
      labels.map(function (l, i) {
        return '<label class="ops-radio-pill"><input type="radio" name="processStatus" value="' + l + '"' + (i === 0 ? ' checked' : '') + '><span>' + l + '</span></label>';
      }).join('') +
      '</div></div></div>';
  }

  function processModalVariant(role, fb) {
    var modal = document.getElementById('feedbackProcessModal');
    if (!modal) return;
    var titleEl = modal.querySelector('.modal-header h2');
    var extraEl = document.getElementById('processExtraFields');
    var effectiveRole = role === 'team' ? 'team' : (role === 'expert' ? 'expert' : 'ops');
    if (titleEl) titleEl.textContent = '处理反馈';
    if (extraEl) extraEl.innerHTML = processStatusRadios(effectiveRole);
  }

  function initListPage() {
    OpsShell.initShell({ module: 'feedback' });
    OpsDispatch.ensureModals();
    renderTrendChart();
    wireFilters();
    renderTable();
  }

  function initDetailPage() {
    OpsShell.initShell({ module: 'feedback' });
    OpsDispatch.ensureModals();
    var id = OpsShell.params().get('id') || 'fb_001';
    var fb = byId(id);
    if (!fb) {
      document.querySelector('.main').innerHTML = '<div class="card" style="padding:24px;text-align:center;">未找到反馈记录<a href="' + OpsShell.href('11-user-feedback.html') + '" class="btn btn-primary" style="margin-left:12px;">返回列表</a></div>';
      return;
    }
    var st = statusTag(fb.status);
    document.getElementById('fbTitle').textContent = fb.title;
    document.getElementById('fbUser').textContent = fb.user;
    document.getElementById('fbTeam').textContent = fb.team;
    document.getElementById('fbStatus').innerHTML = '<span class="tag ' + st[1] + '">' + st[0] + '</span>';
    document.getElementById('fbCreated').textContent = fb.createdAt;
    document.getElementById('fbDesc').textContent = fb.desc;
    document.getElementById('fbSource').textContent = fb.agent || fb.source || '—';
    var priEl = document.getElementById('fbPriority');
    if (priEl) priEl.textContent = fb.type || '—';

    var listLink = document.getElementById('breadcrumbListLink');
    if (listLink) listLink.href = OpsShell.href('11-user-feedback.html');

    document.getElementById('btnProcessFeedback').addEventListener('click', function () {
      processModalVariant(OpsShell.getRole(), fb);
      OpsShell.openModal('feedbackProcessModal');
    });
    document.getElementById('btnDispatchTeam').addEventListener('click', function () { OpsDispatch.openTeam(fb); });
    document.getElementById('btnDispatchExpert').addEventListener('click', function () { OpsDispatch.openExpert(fb); });
    document.getElementById('btnMultiExpert').addEventListener('click', function () { OpsDispatch.openMultiExpert(); });

    document.getElementById('confirmProcessFeedback').addEventListener('click', function () {
      var selected = document.querySelector('input[name="processStatus"]:checked');
      var note = document.getElementById('processNoteInput');
      var noteVal = note ? note.value.trim() : '';
      if (selected && selected.value === '已完成') fb.status = 'resolved';
      else if (selected) fb.status = 'processing';
      if (note && noteVal) { /* optional note */ }
      save(load().map(function (x) { return x.id === fb.id ? fb : x; }));
      OpsShell.closeModal('feedbackProcessModal');
      Proto.toast('处理状态已更新：' + (selected ? selected.value : '已保存'));
      var stEl = document.getElementById('fbStatus');
      var st2 = statusTag(fb.status);
      if (stEl) stEl.innerHTML = '<span class="tag ' + st2[1] + '">' + st2[0] + '</span>';
    });

    if (OpsShell.params().get('action') === 'dispatch') {
      setTimeout(function () { OpsDispatch.openTeam(fb); }, 300);
    }
  }

  global.OpsUserFeedback = {
    load: load,
    save: save,
    byId: byId,
    FIGMA_AGENTS: FIGMA_AGENTS,
    initListPage: initListPage,
    initDetailPage: initDetailPage
  };
})(window);

