const fs = require('fs');
const path = require('path');
const t = fs.readFileSync(path.join(__dirname, '../figma-extract/05-ops-platform-nodes.json'), 'utf8');
const start = t.indexOf('"id":  "243:6859"');
const end = t.indexOf('"id":  "243:7114"', start);
const chunk = t.slice(start, end > 0 ? end : start + 500000);
const re = /characters=\s*([^;]+);/g;
const set = new Set();
let m;
while ((m = re.exec(chunk))) set.add(m[1].replace(/\\n/g, '\n'));
console.log([...set].sort().join('\n---\n'));

